// Generated by npm run gen:icon from build/icon-source.png.
const LOGO_BASE64 = ''

let cached: Uint8Array<ArrayBuffer> | null = null

export function logoPng(): Uint8Array<ArrayBuffer> {
  if (cached) return cached
  const bin = atob(LOGO_BASE64)
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
  cached = out
  return out
}
